/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `UPDATECATEGORY` AFTER UPDATE ON `tbl_product_categories`

            FOR EACH ROW 

            BEGIN

                IF new.prodcat_parent != old.prodcat_parent THEN 

                    CALL UPDATECATEGORYRELATIONS(new.prodcat_id);

