INSERT INTO `tbl_product_categories_lang` VALUES (109,1,'Electronics','',''),(109,2,'إلكترونيات','',''),(110,1,'Televisions','',''),(110,2,'التلفزيون','',''),(111,1,'Washing Machines','',''),(111,2,'غسالة ملابس','',''),(112,1,'Men','',''),(112,2,'رجالي','',''),(113,1,'Women','',''),(113,2,'على الموضة للنساء','',''),(114,1,'Jeans','',''),(114,2,'جينز','',''),(116,1,'Bottom wear','',''),(116,2,'جينز وملابس أسفل','',''),(117,1,'Mobiles & Accessories','',''),(117,2,'موبايلات و اكسسواراتها','',''),(119,1,'Shirts','',''),(119,2,'قمصان','',''),(120,1,'Topwear','',''),(120,2,'بلايز و تي شيرت','',''),(121,1,'Gaming Consoles','','A video game console is an electronic, digital or computer device that outputs a video signal or visual image to display a video game that one or more people can play.'),(121,2,'لعب لوحات المفاتيح','','<pre class=\"tw-data-text tw-ta tw-text-small\" data-placeholder=\"Translation\" id=\"tw-target-text\" data-fulltext=\"\" dir=\"rtl\" style=\"unicode-bidi: isolate; background-color: rgb(255, 255, 255); border: none; padding: 0px 0.14em 0px 0px; position: relative; margin-top: 0px; margin-bottom: 0px; resize: none; font-family: inherit; overflow: hidden; text-align: right; width: 276px; white-space: pre-wrap; word-wrap: break-word; color: rgb(33, 33, 33); height: 96px; font-size: 16px !important; line-height: 24px !important;\"><span lang=\"ar\">وحدة تحكم ألعاب الفيديو عبارة عن جهاز إلكتروني أو رقمي أو جهاز كمبيوتر ينتج إشارة فيديو أو صورة مرئية لعرض لعبة فيديو يمكن لشخص واحد أو أكثر تشغيلها.</span></pre>'),(122,1,'Laptops & Accessories','','<span style=\"color: rgb(85, 85, 85); font-family: \"Amazon Ember\", Arial, sans-serif; font-size: 13px; background-color: rgb(255, 255, 255);\">Check out the wide range of top class laptops available on YoKart. Shop for a range of Laptops from top brands like&nbsp;</span><a href=\"http://www.amazon.in/b?node=4364643031\" style=\"box-sizing: border-box; color: rgb(0, 102, 192); font-family: \"Amazon Ember\", Arial,