/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER ON_USERS_UPDATE

            AFTER UPDATE

            ON tbl_users

            FOR EACH ROW

            BEGIN

                IF NEW.user_deleted != OLD.user_deleted THEN

                    CALL updateShopUserValid(NEW.user_id,'','');

                END IF;      

            END */;;
